                 day:"2025-04-02", units:7};

function temporary(t) {
  const dir = mkdtempSync(join(tmpdir(), "orchid-quota-"));
  t.after(() => rmSync(dir, {recursive:true, force:true}));
  return dir;
}

test("Studio applies higher, lower and fallback tenant quotas; Archive is unchanged", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch({...request, id:"iris-full", tenant:"iris", units:3}),
                   {status:"full", id:"iris-full", remaining:2});
  assert.equal(dispatch({...request, id:"iris-ok", tenant:"iris", units:2}).status, "booked");
  assert.deepEqual(dispatch({...request, id:"other", tenant:"lily", units:6}),
                   {status:"full", id:"other", remaining:5});
  assert.equal(dispatch({...request, id:"other", tenant:"lily", units:5}).status, "booked");
  assert.deepEqual(dispatch({...request, service:"archive"}),
                   {status:"full", id:"first", remaining:5});
  assert.equal(dispatch({...request, service:"archive", tenant:"iris", units:5}).status, "booked");
  assert.equal(catalog.default, 5);
});

test("replay, conflicts, cancellation and tenant/day accounting stay in the ledger", () => {
  const dispatch = planner(catalog);
  dispatch(request);
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:1}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"overflow", units:2}),
                   {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...request, id:"tomorrow", day:"2025-04-03", units:8}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.deepEqual(dispatch({...request, id:"replacement", units:8}),
                   {status:"booked", id:"replacement", remaining:0});
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}),
                   {units:8});
  assert.equal(dispatch({service:"studio", action:"summary"}).events.length, 4);
  assert.deepEqual(apply(dispatch, {...request, id:"invalid", units:0}),
                   {status:"invalid", field:"units"});
});

test("renewals use inherited tenant quotas, shared daily usage and existing replay rules", () => {
  const dispatch = planner(catalog);
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first", id:"next", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:1}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"same-day", day:renewal.day, units:2}),
                   {status:"full", id:"same-day", remaining:1});
  assert.equal(dispatch({...renewal, id:"too-big", day:"2025-06-02", units:9}).status, "full");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"first"});
  for (const [service, tenant, units] of [["studio","iris",2], ["studio","lily",5], ["archive","orchid",5]]) {
    dispatch({...request, service, tenant, id:"seed", units});
    assert.equal(dispatch({...renewal, service, previous:"seed", units:units + 1}).status, "full");
    assert.equal(dispatch({...renewal, service, previous:"seed"}).status, "booked");
  }
});

test("imports still bypass admission and count against subsequent Studio bookings", () => {
  const dispatch = planner(catalog);
